import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_W 16
#define TILE_H 16

__global__ void conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int H, int W,
    int C_out, int K,
    int stride, int padding, int dilation,
    int groups,
    int H_out, int W_out,
    int in_tile_h, int in_tile_w)
{
    extern __shared__ float smem[];

    int tile_w = blockDim.x;
    int tile_h = blockDim.y;

    int out_x0 = blockIdx.x * tile_w;
    int out_y0 = blockIdx.y * tile_h;

    int nc = blockIdx.z;
    int n = nc / C_out;
    int oc = nc % C_out;

    int channels_per_group_in = C_in / groups;
    int channels_per_group_out = C_out / groups;
    int g = oc / channels_per_group_out;

    int tx = threadIdx.x;
    int ty = threadIdx.y;

    int out_x = out_x0 + tx;
    int out_y = out_y0 + ty;

    float acc = 0.0f;

    int in_x0 = out_x0 * stride - padding;
    int in_y0 = out_y0 * stride - padding;

    int total_smem_elems = in_tile_h * in_tile_w;
    int tid = ty * tile_w + tx;
    int num_threads = tile_w * tile_h;

    for (int ic = 0; ic < channels_per_group_in; ic++) {
        int in_c = g * channels_per_group_in + ic;

        for (int idx = tid; idx < total_smem_elems; idx += num_threads) {
            int sy = idx / in_tile_w;
            int sx = idx % in_tile_w;
            int gy = in_y0 + sy;
            int gx = in_x0 + sx;
            float val = 0.0f;
            if (gy >= 0 && gy < H && gx >= 0 && gx < W) {
                val = input[((n * C_in + in_c) * H + gy) * W + gx];
            }
            smem[idx] = val;
        }
        __syncthreads();

        if (out_x < W_out && out_y < H_out) {
            const float* w_ptr = weight + ((size_t)oc * channels_per_group_in + ic) * K * K;
            for (int ky = 0; ky < K; ky++) {
                int sy = ty * stride + ky * dilation;
                const float* smem_row = smem + sy * in_tile_w + tx * stride;
                const float* w_row = w_ptr + ky * K;
                for (int kx = 0; kx < K; kx++) {
                    acc += smem_row[kx * dilation] * w_row[kx];
                }
            }
        }
        __syncthreads();
    }

    if (out_x < W_out && out_y < H_out) {
        if (bias != nullptr) {
            acc += bias[oc];
        }
        output[((n * C_out + oc) * H_out + out_y) * W_out + out_x] = acc;
    }
}

torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups)
{
    input = input.contiguous();
    weight = weight.contiguous();

    int N = input.size(0);
    int C_in = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    int C_out = weight.size(0);
    int K = weight.size(2);

    int H_out = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    int W_out = (W + 2 * padding - dilation * (K - 1) - 1) / stride + 1;

    auto output = torch::zeros({N, C_out, H_out, W_out}, input.options());

    dim3 block(TILE_W, TILE_H);
    dim3 grid(
        (W_out + TILE_W - 1) / TILE_W,
        (H_out + TILE_H - 1) / TILE_H,
        N * C_out
    );

    int in_tile_w = (TILE_W - 1) * stride + (K - 1) * dilation + 1;
    int in_tile_h = (TILE_H - 1) * stride + (K - 1) * dilation + 1;

    size_t smem_size = (size_t)in_tile_h * in_tile_w * sizeof(float);

    const float* bias_ptr = nullptr;
    if (bias.defined() && bias.numel() > 0) {
        bias = bias.contiguous();
        bias_ptr = bias.data_ptr<float>();
    }

    conv2d_kernel<<<grid, block, smem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C_in, H, W,
        C_out, K,
        stride, padding, dilation,
        groups,
        H_out, W_out,
        in_tile_h, in_tile_w
    );

    return output;
}
"""

conv2d_cpp_source = r"""
torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups);
"""

conv2d_module = load_inline(
    name="custom_conv2d",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_source,
    functions=["conv2d_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1,
                 padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.has_bias = bias

        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size)
        )
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
            fan_in = (in_channels // groups) * kernel_size * kernel_size
            bound = 1 / (fan_in ** 0.5)
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

        self.conv2d_forward = conv2d_module.conv2d_forward

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.cuda().contiguous()
        bias = self.bias.cuda() if self.bias is not None else torch.tensor([], device=x.device, dtype=x.dtype)

        return self.conv2d_forward(
            x, weight, bias,
            self.stride, self.padding, self.dilation, self.groups
        )


